async function searchTrackIdsByFts(env, q, limit = 200) {
  const ftsQuery = buildFtsQuery(q);
  if (!ftsQuery) return [];
  try {
    const result = await env.DB.prepare(`
      SELECT track_id
      FROM track_search_fts
      WHERE track_search_fts MATCH ?
      LIMIT ?
    `).bind(ftsQuery, limit).all();
    return (result.results || []).map((row) => String(row.track_id || "")).filter(Boolean);
  } catch (error) {
    console.warn("[Explore Search] track FTS fallback", error);
    return [];
  }
}
