async function handleSearch(url, env, cors) {
  const q = safeString(url.searchParams.get("q")).trim();
  if (!q) {
    return apiError("SEARCH_QUERY_REQUIRED", "\uAC80\uC0C9\uC5B4\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.", 400, cors);
  }
  if (q.length > MAX_SEARCH_LENGTH) {
    return apiError("SEARCH_QUERY_TOO_LONG", "\uAC80\uC0C9\uC5B4\uAC00 \uB108\uBB34 \uAE41\uB2C8\uB2E4.", 400, cors);
  }
  const limit = getPageSize(url);
  const creatorLimitRaw = Number(url.searchParams.get("creatorLimit") || 10);
  const creatorLimit = Number.isFinite(creatorLimitRaw) ? Math.min(20, Math.max(5, Math.floor(creatorLimitRaw))) : 10;
  const cursor = decodeCursor(url.searchParams.get("cursor"));
  const [ftsTrackIds, ftsCreatorIds] = await Promise.all([
    searchTrackIdsByFts(env, q),
    searchCreatorIdsByFts(env, q)
  ]);
  const like = `%${escapeLike(q)}%`;
  const prefix = `${escapeLike(q)}%`;
  const ftsTrackClause = ftsTrackIds.length ? ` OR t.id IN (${ftsTrackIds.map(() => "?").join(",")})` : "";
  const creatorOwnerClause = ftsCreatorIds.length ? ` OR t.owner_uid IN (${ftsCreatorIds.map(() => "?").join(",")})` : "";
  const candidateBindings = [q, prefix, like, like, like, like];
  if (ftsTrackIds.length) candidateBindings.push(...ftsTrackIds);
  if (ftsCreatorIds.length) candidateBindings.push(...ftsCreatorIds);
  let rankedCursorSql = "";
  const cursorBindings = [];
  if (cursor) {
    const priority = Number(cursor.priority);
    const publishedAt = Number(cursor.publishedAt);
    const id = safeString(cursor.id);
    if (Number.isFinite(priority) && Number.isFinite(publishedAt) && id) {
      rankedCursorSql = `
        WHERE (
          search_priority > ?
          OR (
            search_priority = ?
            AND (
              published_at < ?
              OR (published_at = ? AND id < ?)
            )
          )
        )`;
      cursorBindings.push(priority, priority, publishedAt, publishedAt, id);
    }
  }
  const trackResult = await env.DB.prepare(`
    WITH candidates AS (
      SELECT
        t.*,
        p.nickname AS owner_nickname,
        p.avatar_url AS owner_avatar_url,
        COALESCE(s.like_count, 0) AS like_count,
        COALESCE(s.comment_count, 0) AS comment_count,
        COALESCE(s.play_count, 0) AS play_count,
        CASE
          WHEN t.title = ? COLLATE NOCASE THEN 0
          WHEN t.title LIKE ? ESCAPE '\\' THEN 1
          ELSE 2
        END AS search_priority
      FROM tracks t
      LEFT JOIN public_profiles p
        ON p.uid = t.owner_uid AND p.is_public = 1
      LEFT JOIN track_stats s
        ON s.track_id = t.id
      WHERE t.is_public = 1
        AND t.status = 'published'
        AND (
          t.title LIKE ? ESCAPE '\\'
          OR t.search_text LIKE ? ESCAPE '\\'
          OR EXISTS (
            SELECT 1
            FROM track_tags tt
            WHERE tt.track_id = t.id
              AND tt.value LIKE ? ESCAPE '\\'
          )
          OR p.nickname LIKE ? ESCAPE '\\'
          ${ftsTrackClause}
          ${creatorOwnerClause}
        )
    )
    SELECT * FROM candidates
    ${rankedCursorSql}
    ORDER BY search_priority ASC, published_at DESC, id DESC
    LIMIT ?
  `).bind(...candidateBindings, ...cursorBindings, limit + 1).all();
  const trackRows = trackResult.results || [];
  const hasMore = trackRows.length > limit;
  const visibleTracks = trackRows.slice(0, limit);
  const items = visibleTracks.map(mapTrackRow);
  const last = visibleTracks[visibleTracks.length - 1];
  const nextCursor = hasMore && last ? encodeCursor({
    priority: Number(last.search_priority || 0),
    publishedAt: Number(last.published_at || 0),
    id: last.id
  }) : null;
  const creatorBindings = [q, prefix, like];
  const creatorFtsClause = ftsCreatorIds.length ? ` OR p.uid IN (${ftsCreatorIds.map(() => "?").join(",")})` : "";
  if (ftsCreatorIds.length) creatorBindings.push(...ftsCreatorIds);
  const creatorResult = await env.DB.prepare(`
    SELECT
      p.uid,
      p.nickname,
      p.avatar_url,
      p.bio,
      COALESCE(ps.follower_count, 0) AS follower_count,
      COALESCE(ps.following_count, 0) AS following_count,
      (SELECT COUNT(*) FROM tracks t
        WHERE t.owner_uid = p.uid AND t.is_public = 1 AND t.status = 'published') AS track_count,
      CASE
        WHEN p.nickname = ? COLLATE NOCASE THEN 0
        WHEN p.nickname LIKE ? ESCAPE '\\' THEN 1
        ELSE 2
      END AS search_priority
    FROM public_profiles p
    LEFT JOIN profile_stats ps ON ps.uid = p.uid
    WHERE p.is_public = 1
      AND (
        p.nickname LIKE ? ESCAPE '\\'
        ${creatorFtsClause}
      )
    ORDER BY search_priority ASC, follower_count DESC, p.updated_at DESC
    LIMIT ?
  `).bind(...creatorBindings, creatorLimit).all();
  const creators = (creatorResult.results || []).map((row) => ({
    uid: row.uid,
    nickname: row.nickname || "",
    avatarUrl: row.avatar_url || "",
    bio: row.bio || "",
    followerCount: Number(row.follower_count || 0),
    followingCount: Number(row.following_count || 0),
    trackCount: Number(row.track_count || 0)
  }));
  return json({
    ok: true,
    data: {
      query: q,
      items,
      tracks: { items, nextCursor },
      creators,
      nextCursor
    }
  }, 200, cors);
}
