async function syncExploreFeedR2PublicVisibility1028(env, trackId) {
  try {
    const row = await env.DB.prepare(`
      SELECT t.*, p.nickname AS owner_nickname, p.avatar_url AS owner_avatar_url,
        COALESCE(s.like_count,0) AS like_count,
        COALESCE(s.comment_count,0) AS comment_count,
        COALESCE(s.play_count,0) AS play_count
      FROM tracks t
      LEFT JOIN public_profiles p ON p.uid = t.owner_uid AND p.is_public = 1
      LEFT JOIN track_stats s ON s.track_id = t.id
      WHERE t.id = ? AND t.is_public = 1 AND t.status = 'published'
      LIMIT 1
    `).bind(trackId).first();
    if (!row) {
      await syncExploreFeedR2Private017(env, trackId);
      return;
    }
    await syncExploreFeedR2Publication012(env, mapTrackRow(row));
  } catch (error) {
    console.warn("[SORIDRAW visibility] bounded feed delta skipped:", String(error?.message || error || "unknown"));
  }
}
