async function refreshTrackSearchIndex(env, trackId) {
  const track = await env.DB.prepare(`
    SELECT id, title FROM tracks WHERE id = ? AND is_public = 1 AND status = 'published' LIMIT 1
  `).bind(trackId).first();
  const statements = [env.DB.prepare("DELETE FROM track_search_fts WHERE track_id = ?").bind(trackId)];
  if (track) {
    statements.push(env.DB.prepare(`
      INSERT INTO track_search_fts (track_id, title, genre, style, mood, tags)
      SELECT
        t.id,
        COALESCE(t.title,''),
        COALESCE((SELECT GROUP_CONCAT(value,' ') FROM track_tags WHERE track_id=t.id AND kind='genre'),''),
        COALESCE((SELECT GROUP_CONCAT(value,' ') FROM track_tags WHERE track_id=t.id AND kind='style'),''),
        COALESCE((SELECT GROUP_CONCAT(value,' ') FROM track_tags WHERE track_id=t.id AND kind='mood'),''),
        COALESCE((SELECT GROUP_CONCAT(value,' ') FROM track_tags WHERE track_id=t.id),'')
      FROM tracks t WHERE t.id = ?
    `).bind(trackId));
  }
  await env.DB.batch(statements);
}
