async function refreshFollowStats(env, followerUid, followingUid, now) {
  await env.DB.batch([
    env.DB.prepare(`
      INSERT INTO profile_stats (uid, follower_count, following_count, updated_at)
      VALUES (?, 0, 0, ?)
      ON CONFLICT(uid) DO NOTHING
    `).bind(followerUid, now),
    env.DB.prepare(`
      INSERT INTO profile_stats (uid, follower_count, following_count, updated_at)
      VALUES (?, 0, 0, ?)
      ON CONFLICT(uid) DO NOTHING
    `).bind(followingUid, now),
    env.DB.prepare(`
      UPDATE profile_stats
      SET following_count = (SELECT COUNT(*) FROM follows WHERE follower_uid = ?), updated_at = ?
      WHERE uid = ?
    `).bind(followerUid, now, followerUid),
    env.DB.prepare(`
      UPDATE profile_stats
      SET follower_count = (SELECT COUNT(*) FROM follows WHERE following_uid = ?), updated_at = ?
      WHERE uid = ?
    `).bind(followingUid, now, followingUid)
  ]);
}
