async function buildMusicNotePublicationR2Payload(env, uid) {
  const result = await env.DB.prepare(`
    SELECT id, source_id, is_public, allow_next_song_apply, allow_follower_save, profile_pinned
    FROM tracks
    WHERE owner_uid = ?
      AND source_type = 'music_note'
      AND source_id IS NOT NULL
      AND source_id <> ''
  `).bind(uid).all();
  const states = {};
  for (const row of result.results || []) {
    const sourceId = String(row.source_id || "").trim();
    const trackId = String(row.id || "").trim();
    if (!sourceId || !trackId) continue;
    states[sourceId] = {
      status: Number(row.is_public || 0) === 1 ? "public" : "private",
      trackId,
      allowNextSongApply: Number(row.allow_next_song_apply || 0) === 1,
      allowFollowerSave: Number(row.allow_follower_save || 0) === 1,
      profilePinned: Number(row.profile_pinned || 0) === 1
    };
  }
  return { schemaVersion: MUSIC_NOTE_PUBLICATION_R2_SCHEMA_VERSION, states, itemCount: Object.keys(states).length, updatedAt: Date.now() };
}
