async function handleMyPublications(request, url, env, cors) {
  const authContext = await requireExploreAuth(request);
  const limit = getPageSize(url);
  const visibility = safeString(url.searchParams.get("visibility") || "all").toLowerCase();
  if (!["all", "public", "private"].includes(visibility)) throwApi("INVALID_VISIBILITY_FILTER", "\uACF5\uAC1C \uC0C1\uD0DC \uD544\uD130\uAC00 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", 400);
  const visibilitySql = visibility === "public" ? "AND t.is_public = 1" : visibility === "private" ? "AND t.is_public = 0" : "";
  const cursor = decodeCursor(url.searchParams.get("cursor"));
  const bindings = [authContext.uid];
  let cursorSql = "";
  if (cursor) {
    const updatedAt = Number(cursor.updatedAt);
    const id = safeString(cursor.id);
    if (Number.isFinite(updatedAt) && id) {
      cursorSql = "AND (t.updated_at < ? OR (t.updated_at = ? AND t.id < ?))";
      bindings.push(updatedAt, updatedAt, id);
    }
  }
  const result = await env.DB.prepare(`
    SELECT t.*, p.nickname AS owner_nickname, p.avatar_url AS owner_avatar_url,
      COALESCE(s.like_count,0) AS like_count,
      COALESCE(s.comment_count,0) AS comment_count,
      COALESCE(s.play_count,0) AS play_count
    FROM tracks t
    LEFT JOIN public_profiles p ON p.uid=t.owner_uid
    LEFT JOIN track_stats s ON s.track_id=t.id
    WHERE t.owner_uid = ? ${visibilitySql} ${cursorSql}
    ORDER BY t.updated_at DESC, t.id DESC
    LIMIT ?
  `).bind(...bindings, limit + 1).all();
  const rows = result.results || [];
  const hasMore = rows.length > limit;
  const visible = rows.slice(0, limit);
  const last = visible[visible.length - 1];
  return json({ ok: true, data: {
    items: visible.map((row) => ({ ...mapTrackRow(row), isPublic: Number(row.is_public || 0) === 1 })),
    nextCursor: hasMore && last ? encodeCursor({ updatedAt: Number(last.updated_at || 0), id: last.id }) : null
  } }, 200, cors);
}
