  const sortOrder = Number.isFinite(Number(body.sortOrder)) ? Math.max(-1e5, Math.min(1e5, Math.floor(Number(body.sortOrder)))) : 0;
  const startsAt = body.startsAt == null ? null : Number(body.startsAt);
  const endsAt = body.endsAt == null ? null : Number(body.endsAt);
