async function upsertPublicProfileFromFirebase(env, authContext, now) {
  const userData = await fetchFirestoreDocument(["users", authContext.uid], authContext);
  if (!userData) {
    throwApi("USER_PROFILE_NOT_FOUND", "\uC0AC\uC6A9\uC790 \uD504\uB85C\uD544\uC744 \uD655\uC778\uD558\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4.", 409);
  }
  const emailPrefix = String(authContext.email || "").split("@")[0].trim();
  const nickname = firstNonEmptyString(
    userData.nickname,
    userData.displayName,
    authContext.displayName,
    emailPrefix,
    "SORIDRAW \uC0AC\uC6A9\uC790"
  ).slice(0, 80);
  const avatarUrl = firstNonEmptyString(userData.photoURL, authContext.picture).slice(0, 4e3);
  await env.DB.prepare(`
    INSERT INTO public_profiles (
      uid, nickname, avatar_url, bio, is_public, created_at, updated_at
    ) VALUES (?, ?, ?, '', 1, ?, ?)
    ON CONFLICT(uid) DO UPDATE SET
      nickname = CASE WHEN public_profiles.profile_customized = 1 THEN public_profiles.nickname ELSE excluded.nickname END,
      avatar_url = CASE WHEN public_profiles.profile_customized = 1 THEN public_profiles.avatar_url ELSE excluded.avatar_url END,
      is_public = 1,
      updated_at = excluded.updated_at
  `).bind(authContext.uid, nickname, avatarUrl, now, now).run();
  await refreshProfileSearchIndex(env, authContext.uid);
  const row = await env.DB.prepare(`
    SELECT nickname, avatar_url FROM public_profiles WHERE uid = ? LIMIT 1
  `).bind(authContext.uid).first();
  return {
    uid: authContext.uid,
    nickname: row?.nickname || nickname,
    avatarUrl: row?.avatar_url || avatarUrl
  };
}
