async function handlePublicProfileFolders(uid, env, cors) {
  const profile = await env.DB.prepare(`
    SELECT uid FROM public_profiles WHERE uid = ? AND is_public = 1 LIMIT 1
  `).bind(uid).first();
  if (!profile) return apiError("NOT_FOUND", "\uACF5\uAC1C \uD504\uB85C\uD544\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", 404, cors);
  const result = await env.DB.prepare(`
    SELECT pf.id, pf.source_folder_id, pf.title, pf.updated_at,
      SUM(CASE WHEN t.is_public = 1 AND t.status = 'published' THEN 1 ELSE 0 END) AS track_count
    FROM public_folders pf
    LEFT JOIN public_folder_tracks pft ON pft.folder_id = pf.id
    LEFT JOIN tracks t ON t.id = pft.track_id
    WHERE pf.owner_uid = ? AND pf.is_public = 1
    GROUP BY pf.id
    ORDER BY pf.updated_at DESC, pf.id DESC
  `).bind(uid).all();
  const items = (result.results || []).map((row) => ({
    id: row.id,
    sourceFolderId: row.source_folder_id,
    title: row.title || "",
    trackCount: Number(row.track_count || 0),
    updatedAt: Number(row.updated_at || 0)
  })).filter((item) => item.trackCount > 0);
  return json({ ok: true, data: { items } }, 200, cors);
}
